<template><section class="space-y-5"><h1 class="text-2xl font-bold text-white">结算与打款</h1><div v-for="item in items" :key="item.id" class="pc-card"><p class="font-semibold text-white">{{ money(item.amount_minor,item.currency) }}</p><p class="text-sm text-slate-400">{{ item.status }} · Order {{ item.order_id }}</p></div><p v-if="!items.length" class="pc-card text-slate-400">暂无打款记录</p><p v-if="error" class="text-red-300">{{ error }}</p></section></template>
<script setup lang="ts">definePageMeta({layout:'procurement',middleware:['auth']});const {apiFetch}=useApi();const items=ref<any[]>([]);const error=ref('');const money=(v:number,c:string)=>new Intl.NumberFormat(undefined,{style:'currency',currency:c}).format(v/100);onMounted(async()=>{try{items.value=(await apiFetch<any>('/cebu-trade/payouts')).items}catch(e:any){error.value=e?.data?.detail||e?.message}})</script>
